import { lessonRequest } from './request';

export function browseShelves(zone: string) {
  const query = new URLSearchParams({ zone });
  return lessonRequest({ path: '/shelves', query });
}

export function reserveCopy(copyKey: string, days: number, patronScope: string) {
  const payload: Record<string, unknown> = { days };
  Object.assign(payload, { notify_reader: true });
  return lessonRequest({
    path: `/copies/${encodeURIComponent(copyKey)}/reservations`,
    method: 'POST',
    headers: { 'X-Patron-Scope': patronScope },
    body: JSON.stringify(payload),
  });
}
