interface LessonRequest {
  path: string;
  method?: string;
  query?: URLSearchParams;
  headers?: Record<string, string>;
  body?: BodyInit;
}

const lessonRoot = '/reading-room/v3';
const lessonHeaders = { 'X-Reading-Lesson': 'bundle-contexts' };

export function lessonRequest(contract: LessonRequest) {
  const suffix = contract.query ? `?${contract.query.toString()}` : '';
  const options: RequestInit = { method: 'GET' };
  Object.assign(options, { method: contract.method ?? options.method, body: contract.body });
  options.headers = { ...lessonHeaders, ...contract.headers };
  return fetch(`${lessonRoot}${contract.path}${suffix}`, options);
}
